<script setup lang="ts">import {Eye,EyeOff} from 'lucide-vue-next';definePageMeta({layout:false});const identifier=ref(''),password=ref(''),show=ref(false),error=ref(''),loading=ref(false);async function login(){error.value='';loading.value=true;try{await $fetch('/api/auth/login',{method:'POST',body:{identifier:identifier.value,password:password.value}});await navigateTo('/admin/dashboard')}catch(e:any){error.value=e.data?.statusMessage||'Tidak dapat masuk.'}finally{loading.value=false}};useSeoMeta({title:'Masuk Admin | ProShop',robots:'noindex'})</script><template><main class="login"><form class="panel" @submit.prevent="login"><BrandLogo/><div><h1>Masuk ke backoffice</h1><p class="muted">Kelola katalog dan pergerakan stok ProShop.</p></div><div><label class="label" for="identifier">Username</label><input id="identifier" v-model="identifier" class="field" autocomplete="username" required></div><div><label class="label" for="password">Password</label><div class="password"><input id="password" v-model="password" class="field" :type="show?'text':'password'" autocomplete="current-password" minlength="8" required><button type="button" :aria-label="show?'Sembunyikan password':'Tampilkan password'" @click="show=!show"><component :is="show?EyeOff:Eye" :size="18"/></button></div></div><p v-if="error" class="error">{{error}}</p><button class="btn btn-primary" :disabled="loading">{{loading?'Memeriksa…':'Masuk'}}</button><small class="credentials">username=admin , password=admin12345</small></form></main></template><style scoped>.login{min-height:100vh;display:grid;place-items:center;background:var(--surface);padding:1rem}.panel{width:min(420px,100%);padding:2rem;display:grid;gap:1.3rem}.panel h1{margin:0;font-size:1.7rem}.panel p{margin:.35rem 0}.password{position:relative}.password button{position:absolute;right:.6rem;top:.7rem;border:0;background:none}.panel>.btn{width:100%}.credentials{text-align:center;color:var(--muted);font-size:.72rem}</style>
